import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

/* STAFF NAVBAR */
import StaffNavbar from "../components/StaffNavbar";

export default function Orders() {

  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  /* =========================
     FETCH ORDERS
  ========================= */
  const fetchOrders = async () => {

    try {

      const res = await fetch(
        "http://localhost/Capstone--Development/staff/api_orders.php"
      );

      const data = await res.json();

      if (!Array.isArray(data)) {
        setOrders([]);
        setError("Invalid API response");
        return;
      }

      const parsed = data.map(order => {

        let items = [];

        try {
          items =
            typeof order.items === "string"
              ? JSON.parse(order.items || "[]")
              : order.items || [];
        } catch (e) {
          items = [];
        }

        return {
          ...order,
          items
        };

      });

      setOrders(parsed);

    } catch (err) {
      console.error(err);
      setError("Failed to fetch orders");
      setOrders([]);
    } finally {
      setLoading(false);
    }

  };

  useEffect(() => {
    fetchOrders();
  }, []);

  /* =========================
     UPDATE STATUS
  ========================= */
  const updateStatus = async (id, status) => {

    try {

      const res = await fetch(
        "http://localhost/Capstone--Development/staff/api_update_order_status.php",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ id, status })
        }
      );

      const data = await res.json();

      if (data.success || data.status === "success") {
        fetchOrders();
      } else {
        console.error("Update failed:", data);
      }

    } catch (err) {
      console.error("Update error:", err);
    }

  };

  const statusColors = {
    Pending: "bg-yellow-100 text-yellow-700",
    Preparing: "bg-blue-100 text-blue-700",
    "To Receive": "bg-purple-100 text-purple-700",
    Completed: "bg-green-100 text-green-700",
  };

  return (

    <div className="bg-[#fafafa] min-h-screen">

      {/* NAVBAR */}
      <StaffNavbar />

      <div className="p-8 xl:p-10">

        {/* HEADER */}
        <div className="mb-10 pt-20">
          <p className="text-[10px] uppercase tracking-[0.3em] text-gray-400">
            Staff Control Panel
          </p>

          <h1 className="text-3xl font-bold">
            Orders Management
          </h1>
        </div>

        {/* ERROR */}
        {error && (
          <p className="text-red-500 mb-4">
            {error}
          </p>
        )}

        {/* LOADING */}
        {loading ? (
          <p className="text-gray-400">Loading orders...</p>
        ) : orders.length === 0 ? (
          <p className="text-gray-400">No orders found</p>
        ) : (

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

            {orders.map(order => (

              <motion.div
                key={order.id}
                whileHover={{ y: -5 }}
                className="bg-white rounded-[25px] p-6 shadow-lg border border-gray-100"
              >

                {/* HEADER */}
                <div className="flex justify-between mb-4">

                  <div>
                    <p className="text-[10px] text-gray-400 uppercase">
                      Order ID
                    </p>
                    <h2 className="font-bold">#{order.id}</h2>
                  </div>

                  <span className={`px-3 py-1 text-[10px] rounded-full ${statusColors[order.status]}`}>
                    {order.status}
                  </span>

                </div>

                {/* ITEMS */}
                <div className="mb-4 space-y-2">

                  {order.items.map((item, i) => (
                    <div key={i} className="flex justify-between text-sm">
                      <span>{item.name} x{item.qty}</span>
                      <span>₱{Number(item.price) * item.qty}</span>
                    </div>
                  ))}

                </div>

                {/* TOTAL */}
                <div className="border-t pt-3 flex justify-between font-semibold">
                  <span>Total</span>
                  <span className="text-[#d4af37]">
                    ₱{Number(order.total).toLocaleString()}
                  </span>
                </div>

                {/* ACTION BUTTONS */}
                <div className="mt-4 flex flex-wrap gap-2">

                  <button onClick={() => updateStatus(order.id, "Pending")}
                    className="px-3 py-1 text-xs bg-yellow-100 text-yellow-700 rounded-full">
                    Pending
                  </button>

                  <button onClick={() => updateStatus(order.id, "Preparing")}
                    className="px-3 py-1 text-xs bg-blue-100 text-blue-700 rounded-full">
                    Preparing
                  </button>

                  <button onClick={() => updateStatus(order.id, "To Receive")}
                    className="px-3 py-1 text-xs bg-purple-100 text-purple-700 rounded-full">
                    To Receive
                  </button>

                  <button onClick={() => updateStatus(order.id, "Completed")}
                    className="px-3 py-1 text-xs bg-green-100 text-green-700 rounded-full">
                    Completed
                  </button>

                </div>

              </motion.div>

            ))}

          </div>

        )}

      </div>

    </div>

  );

}
